{
  "references": [
    {
      "id": "R1",
      "summary_ko": "요청되지 않은 두 번째 말이 존재함",
      "claims": [
        {
          "id": "R1.S1",
          "evidence": "There seems to be second horse that wasn't requested",
          "symptom_ko": "요청되지 않은 두 번째 말이 등장함",
          "role": "complaint"
        }
      ]
    },
    {
      "id": "R2",
      "summary_ko": "줄이 겹쳐져 보이고 카우보이와 너무 가까움",
      "claims": [
        {
          "id": "R2.S1",
          "evidence": "The string seems to be doubled up and too close to the cowboy",
          "symptom_ko": "줄이 겹쳐져 보이고 카우보이와 너무 가까움",
          "role": "complaint"
        }
      ]
    },
    {
      "id": "R3",
      "summary_ko": "화살표가 한 프레임에서 다음 프레임으로 넘어가면서 크기가 줄어듦",
      "claims": [
        {
          "id": "R3.S1",
          "evidence": "The arrow clearly shrinks from one frame to the other",
          "symptom_ko": "화살표가 프레임 간에 분명하게 줄어듦",
          "role": "complaint"
        }
      ]
    },
    {
      "id": "R4",
      "summary_ko": "남자의 오른팔이 더 이상 활시위를 잡고 있지 않는 것으로 보임.",
      "claims": [
        {
          "id": "R4.S1",
          "evidence": "The man's right arm does not appear to be holding the bow's string anymore.",
          "symptom_ko": "남자의 오른팔이 더 이상 활시위를 잡고 있지 않음",
          "role": "complaint"
        }
      ]
    },
    {
      "id": "R5",
      "summary_ko": "영상 끝부분보다 중간 부분에서 남자가 발사 준비에 더 가까워 보여 '발사 준비를 한다'는 프롬프트 지시를 제대로 따르지 못함.",
      "claims": [
        {
          "id": "R5.S1",
          "evidence": "The man actually looks closer to shooting in the middle of the video (body language, arrow and bow position) that at it's end, so the prompt \"prepares to shoot\" hasn't been successfully followed.",
          "symptom_ko": "영상 끝보다 중간에서 남자의 몸짓, 활과 화살 위치가 발사에 더 가까워 보여 '발사 준비' 지시 불이행",
          "role": "complaint"
        }
      ]
    }
  ],
  "candidates": [],
  "pairs": []
}

